        .sort(sortPageComponentsByPath)
        .map((component, i) => (<BaseComponent key={`${regionAttrs.id}-${i}`} component={component} common={common} meta={meta}/>));
    if (meta.renderMode === RENDER_MODE.EDIT) {
        regionAttrs.id = name + 'Region';
