import * as contentLib from '/lib/xp/content';
import * as contextLib from '/lib/xp/context';
import * as exportLib from '/lib/xp/export';
import * as projectLib from '/lib/xp/project';
import * as taskLib from '/lib/xp/task';
import { fixBrokenPageTemplates } from './lib/fix-page-templates';

function ensureStorefrontPageTemplate(): void {
    log.info('[storefront-page-template] checking for storefront-page template…');
    let result: { _id?: string; _path?: string } | null = null;
    try {
        result = contextLib.run(
            { user: { login: 'su', idProvider: 'system' }, repository: 'com.enonic.cms.hmdb', branch: 'draft' },
            () => {
                const templatePath = '/hmdb/_templates/storefront-page';
                const existing = contentLib.get({ key: templatePath });
                if (existing) {
                    log.debug('[storefront-page-template] already exists, skipping');
                    return null;
                }

                const created = contentLib.create({
                    parentPath: '/hmdb/_templates',
                    name: 'storefront-page',
                    displayName: 'Storefront Page',
                    contentType: 'portal:page-template',
                    data: { supports: `${app.name}:storefront-page` } as Record<string, unknown>
                });

                if (!created) {
                    log.error('[storefront-page-template] create returned null');
                    return null;
                }

                contentLib.modify({
                    key: created._id,
                    requireValid: false,
                    editor: (c) => {
                        (c as Record<string, unknown>)['page'] = {
                            descriptor: `${app.name}:main`,
                            customized: false,
                            config: {}
                        };
                        return c;
                    }
                });

                log.info(`[storefront-page-template] created at ${created._path}`);
                return created;
            }
        );
    } catch (e) {
        log.warning('[storefront-page-template] error: ' + (e as Error).message);
        return;
    }

    if (!result) return;

    try {
        contextLib.run(
            { user: { login: 'su', idProvider: 'system' }, repository: 'com.enonic.cms.hmdb', branch: 'draft' },
