import type { PartProps } from '@enonic/nextjs-adapter';
import { listProducts } from '@lib/data/products';
import Image from 'next/image';
import LocalizedClientLink from '@modules/common/components/localized-client-link';

type ProductShowcaseConfig = {
    heading?: string;
    products?: string | string[];
};

export default async function ProductShowcase({ part, meta }: PartProps) {
    const config = (part?.config ?? {}) as ProductShowcaseConfig;
    const heading = config.heading ?? '';
    const raw = config.products;
    const handles: string[] = !raw ? [] : Array.isArray(raw) ? raw.filter(Boolean) : [raw].filter(Boolean);
    const countryCode = meta?.locale ?? 'dk';

    if (!handles.length) {
        return (
            <section className="content-container py-8">
                {heading && <h2 className="text-xl-semi mb-6">{heading}</h2>}
                <p className="text-ui-fg-subtle text-base-regular">No products configured for this showcase.</p>
            </section>
        );
    }

    const { response } = await listProducts({
        countryCode,
        queryParams: { handle: handles } as never,
    });
    const products = response.products;

    return (
        <section className="content-container py-8">
            {heading && <h2 className="text-xl-semi mb-6">{heading}</h2>}
            <div className="grid grid-cols-2 small:grid-cols-3 gap-6">
                {products.map((product) => (
                    <LocalizedClientLink
                        key={product.id}
                        href={`/products/${product.handle}`}
                        className="group"
                    >
                        <div className="aspect-square w-full overflow-hidden bg-ui-bg-subtle relative rounded-large">
                            {product.thumbnail && (
                                <Image
                                    src={product.thumbnail}
                                    alt={product.title || ''}
                                    fill
                                    className="object-cover"
                                />
                            )}
                        </div>
                        <p className="text-base-regular mt-2">{product.title}</p>
                    </LocalizedClientLink>
                ))}
            </div>
        </section>
    );
}

