import { getContent } from '/lib/xp/portal';
import type { Request, Response } from '@enonic-types/core';

export function GET(_req: Request): Response {
    const content = getContent();
    const page = content?.page as Record<string, unknown> | null | undefined;
    const regions = page?.regions as Record<string, { components?: Array<{ descriptor?: string }> }> | undefined;
    const parts = regions?.main?.components || [];

    const partsHtml = parts.map((c) => {
        const name = c.descriptor?.split(':')[1] || 'part';
        return `<div style="padding:0.75rem 1rem;margin:0.5rem 0;background:#eff6ff;border:1px solid #93c5fd;border-radius:4px;font-size:0.85rem;color:#1d4ed8">◆ ${name}</div>`;
    }).join('');

    return {
        body: `<!DOCTYPE html>
<html>
  <head><meta charset="utf-8"></head>
  <body style="font-family:sans-serif;padding:1.5rem;background:#fafafa;margin:0">
    <p style="color:#9ca3af;font-size:0.75rem;margin:0 0 0.75rem">Storefront Page &mdash; live rendering via Next.js frontend</p>
    <div data-portal-region="main" style="min-height:80px;border:2px dashed #d1d5db;border-radius:6px;padding:1rem">
      ${partsHtml || '<p style="color:#9ca3af;font-size:0.85rem;margin:0">Main region &mdash; drop parts here</p>'}
    </div>
  </body>
</html>`,
        contentType: 'text/html'
    };
}

import { getComponent } from '/lib/xp/portal';
import type { PartComponent, Request, Response } from '@enonic-types/core';

export function GET(_req: Request): Response {
    const part = getComponent() as PartComponent | null;
    const config = ((part as Record<string, unknown> | null)?.config || {}) as { heading?: string; products?: string | string[] };
    const heading = config.heading || 'Product Showcase';
    const rawProducts = config.products;
    const products = !rawProducts
        ? []
        : Array.isArray(rawProducts) ? rawProducts : [rawProducts];

    return {
        body: `<div style="font-family:sans-serif;padding:1rem 1.25rem;background:#eff6ff;border:2px solid #3b82f6;border-radius:6px;margin:0.5rem 0">
            <div style="font-weight:600;color:#1d4ed8;margin-bottom:0.25rem">▦ Product Showcase</div>
            ${config.heading ? `<div style="font-weight:500;margin-bottom:0.25rem">${heading}</div>` : ''}
            <div style="font-size:0.8rem;color:#6b7280">${products.length} product(s) selected — rendered live by Next.js</div>
        </div>`,
        contentType: 'text/html'
    };
}

