function ensureStorefrontPageTemplate(): void {
    log.info('[storefront-page-template] checking for storefront-page template…');
    const adminCtx = { user: { login: 'su', idProvider: 'system' }, repository: 'com.enonic.cms.hmdb', branch: 'draft' } as const;
    try {
        contextLib.run(adminCtx, () => {
            const existing = contentLib.get({ key: '/hmdb/_templates/storefront-page' });
            if (existing) {
                log.debug('[storefront-page-template] already exists, skipping');
                return;
            }

            const created = contentLib.create({
                parentPath: '/hmdb/_templates',
                name: 'storefront-page',
                displayName: 'Storefront Page',
                contentType: 'portal:page-template',
                data: { supports: `${app.name}:storefront-page` } as unknown as Record<string, unknown>
            });

            if (!created) {
                log.error('[storefront-page-template] create returned null');
                return;
            }

            contentLib.modify({
                key: created._id,
                requireValid: false,
                editor: (c) => {
                    (c as unknown as Record<string, unknown>)['page'] = {
                        descriptor: `${app.name}:main`,
                        customized: false,
                        config: {}
                    };
                    return c;
                }
            });

            log.info(`[storefront-page-template] created at ${created._path}`);

            contentLib.publish({ keys: [created._path], includeDependencies: false });
            log.info('[storefront-page-template] published');
        });
    } catch (e) {
        log.warning('[storefront-page-template] error: ' + (e as Error).message);
    }
}

