            const templateFolder = folderResult.hits[0];
            log.info(`[storefront-page-template] template folder found at ${templateFolder._path}`);

            // Check for existing storefront-page template (by type + supports value)
            const existingResult = contentLib.query({
                contentTypes: ['portal:page-template'],
                query: `data.supports = '${app.name}:storefront-page'`,
                count: 1
            });
            if (existingResult?.hits?.length) {
                log.debug('[storefront-page-template] already exists, skipping');
                return;
