            });

            if (!created) {
                log.error('[storefront-page-template] create returned null');
                return;
            }

            contentLib.modify({
                key: created._id,
                requireValid: false,
                editor: (c) => {
                    (c as unknown as Record<string, unknown>)['page'] = {
                        descriptor: `${app.name}:main`,
                        customized: false,
                        config: {}
                    };
                    return c;
                }
            });

            log.info(`[storefront-page-template] created at ${created._path}`);
            contentLib.publish({ keys: [created._path], includeDependencies: false });
            log.info('[storefront-page-template] published');
        });
    } catch (e) {
        log.warning('[storefront-page-template] error: ' + (e as Error).message);
    }
}

