import type { PartComponent, Request, Response } from '@enonic-types/core';

export function GET(_req: Request): Response {
    const part = getComponent() as PartComponent | null;
    const config = ((part as unknown as Record<string, unknown>)?.config || {}) as { heading?: string };
    const text = config.heading || 'Heading';
    return {
        body: `<div style="font-family:sans-serif;padding:0.75rem 1rem;background:#f9fafb;border-left:3px solid #6b7280;margin:0.5rem 0">
            <strong style="color:#374151">${text}</strong>
        </div>`,
        contentType: 'text/html'
    };
}

