import {fetchContent, fetchContentPathsForAllLocales} from "@enonic/nextjs-adapter/server";
import MainView from '@enonic/nextjs-adapter/views/MainView';

import "../../../components/_mappings";
import {Metadata} from 'next';
import {draftMode} from 'next/headers';
import React from 'react';

// NB. Using this option with default value bails out static generation !!!
// export const dynamic = 'auto'

// The revalidate option is only available when using the Node.js Runtime.
// This means using the revalidate option with runtime = 'edge' will not work.
export const revalidate = 3600

// PageProps type matches the Next.js route [[...contentPath]]
// where contentPath is optional (can be undefined for root paths)
export type PageProps = {
    countryCode: string,
    contentPath: string[],
}

export default async function Page({params}: { params: Promise<PageProps> }) {
    const {isEnabled: draft} = await draftMode();
    const resolvedParams = await params;

    let data: FetchContentResult;
    try {
        data = await fetchContent({
            locale: resolvedParams.countryCode,
            contentPath: resolvedParams.contentPath || []
        });
    } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        console.error('[contentPath] fetchContent threw:', msg);
        return <pre style={{padding:'1rem',color:'red'}}>fetchContent error: {msg}</pre>;
    }

    const errCode = data?.error?.code;
    const errMsg = data?.error?.message;
    console.log('[contentPath] data.error:', errCode, errMsg, '| meta.catchAll:', (data as any)?.meta?.catchAll, '| meta.canRender:', (data as any)?.meta?.canRender, '| meta.type:', (data as any)?.meta?.type);

    return (
        <pre style={{padding:'1rem',whiteSpace:'pre-wrap',wordBreak:'break-all'}}>
            error: {errCode ?? 'none'} — {errMsg ?? 'none'}{'\n'}
            type: {(data as any)?.meta?.type}{'\n'}
            catchAll: {String((data as any)?.meta?.catchAll)}{'\n'}
            canRender: {String((data as any)?.meta?.canRender)}{'\n'}
        </pre>
    )
};

export async function generateMetadata({params}: { params: Promise<PageProps> }): Promise<Metadata> {
    const resolvedParams = await params;
    const {common} = await fetchContent({
        locale: resolvedParams.countryCode,
        contentPath: resolvedParams.contentPath || []
    });
    return {
        title: common?.get?.displayName || 'Not found',
    };
}

export async function generateStaticParams_disabled(props: { params: PageProps }): Promise<any[]> {
    return await fetchContentPathsForAllLocales('\${site}/');
}

