import {CATCH_ALL, ComponentRegistry} from '@enonic/nextjs-adapter';
import PropsView from '@enonic/nextjs-adapter/views/PropsView';
import {commonQuery, commonVariables} from './queries/common';

import "@enonic/nextjs-adapter/baseMappings";

import MainPage from './enonic/pages/MainPage';
import ProductShowcase from './enonic/parts/ProductShowcase';

// You can set common query for all views here
ComponentRegistry.setCommonQuery([commonQuery, commonVariables]);

// Page mappings
ComponentRegistry.addPage(`${process.env.NEXT_PUBLIC_ENONIC_APP_NAME}:main`, {view: MainPage});

// Part mappings
ComponentRegistry.addPart(
    `${process.env.NEXT_PUBLIC_ENONIC_APP_NAME}:product-showcase`,
    {view: ProductShowcase as unknown as import('react').FC}
);

// Debug
ComponentRegistry.addContentType(CATCH_ALL, {
    view: PropsView
});

